// ─── BAD: annotation on INTERFACE — may be ignored with CGLIB proxy ───
public interface TransferService {
    @Transactional  // CGLIB proxy may NOT see this!
    void transfer(String from, String to, BigDecimal amount);
}

@Service
public class TransferServiceImpl implements TransferService {
    @Override
    public void transfer(String from, String to, BigDecimal amount) {
        // If CGLIB proxy doesn't see interface annotation → NO transaction!
    }
}

// ─── GOOD: annotation on IMPLEMENTATION — always works ───
public interface TransferService {
    void transfer(String from, String to, BigDecimal amount);
}

@Service
public class TransferServiceImpl implements TransferService {
    @Override
    @Transactional(rollbackFor = Exception.class)  // on IMPLEMENTATION — always safe!
    public void transfer(String from, String to, BigDecimal amount) {
        // CGLIB proxy sees the annotation on this class → TX active ✅
    }
}

// ─── BEST: class-level on implementation ───
@Service
@Transactional(readOnly = true)  // class-level on implementation
public class TransferServiceImpl implements TransferService {

    @Override
    public List<Transfer> getHistory(String accountId) { /* readOnly */ }

    @Override
    @Transactional(rollbackFor = Exception.class)  // override for writes
    public void transfer(String from, String to, BigDecimal amount) { /* writable */ }
}
